// Extract request data
const crewMemberId = $input.item.json.crewMemberId;
const prompt = $input.item.json.prompt;
const context = $input.item.json.context || {};

// Analyze prompt complexity
let complexity = 5;

// Length factor
if (prompt.length > 1000) complexity += 1;
if (prompt.length > 2000) complexity += 1;

// Technical keywords
const technicalKeywords = ['implement', 'architecture', 'algorithm', 'optimize', 'design', 'integrate'];
const technicalCount = technicalKeywords.filter(kw => prompt.toLowerCase().includes(kw)).length;
complexity += technicalCount * 0.5;

// Strategic keywords
const strategicKeywords = ['strategy', 'plan', 'coordinate', 'evaluate', 'decide', 'prioritize'];
const strategicCount = strategicKeywords.filter(kw => prompt.toLowerCase().includes(kw)).length;
complexity += strategicCount * 0.5;

// Clamp to 0-10
complexity = Math.min(Math.max(complexity, 0), 10);

// Determine task type
const promptLower = prompt.toLowerCase();
let taskType = 'general';

if (promptLower.includes('strategy') || promptLower.includes('plan')) {
  taskType = 'strategic';
} else if (promptLower.includes('analyze') || promptLower.includes('calculate')) {
  taskType = 'analytical';
} else if (promptLower.includes('design') || promptLower.includes('create')) {
  taskType = 'creative';
} else if (promptLower.includes('implement') || promptLower.includes('code')) {
  taskType = 'technical';
} else if (promptLower.includes('document') || promptLower.includes('explain')) {
  taskType = 'documentation';
}

// Estimate tokens (1 token ≈ 4 characters)
const estimatedTokens = Math.ceil((prompt.length + JSON.stringify(context).length) / 4 * 1.5);

return {
  json: {
    crewMemberId,
    prompt,
    context,
    analysis: {
      complexity,
      taskType,
      estimatedTokens
    }
  }
};

// Select optimal LLM based on analysis
const analysis = $input.item.json.analysis;
const { complexity, taskType, estimatedTokens } = analysis;

// Available models with their characteristics
const models = [
  {
    id: 'anthropic/claude-3.5-sonnet',
    name: 'Claude 3.5 Sonnet',
    contextWindow: 200000,
    costPer1kTokens: 0.003,
    specialties: ['strategic', 'analytical', 'complex_reasoning'],
    performanceRating: 9.5
  },
  {
    id: 'openai/gpt-4-turbo',
    name: 'GPT-4 Turbo',
    contextWindow: 128000,
    costPer1kTokens: 0.01,
    specialties: ['creative', 'technical', 'general'],
    performanceRating: 9.0
  },
  {
    id: 'google/gemini-pro-1.5',
    name: 'Gemini Pro 1.5',
    contextWindow: 1000000,
    costPer1kTokens: 0.0005,
    specialties: ['analytical', 'documentation', 'large_context'],
    performanceRating: 8.5
  },
  {
    id: 'meta-llama/llama-3.1-70b-instruct',
    name: 'Llama 3.1 70B',
    contextWindow: 8192,
    costPer1kTokens: 0.0003,
    specialties: ['technical', 'documentation', 'cost_effective'],
    performanceRating: 8.0
  },
  {
    id: 'anthropic/claude-3-haiku',
    name: 'Claude 3 Haiku',
    contextWindow: 200000,
    costPer1kTokens: 0.00025,
    specialties: ['fast_response', 'documentation', 'simple_tasks'],
    performanceRating: 7.5
  }
];

// Filter models by specialty
let candidates = models.filter(m => 
  m.specialties.includes(taskType) || m.specialties.includes('general')
);

if (candidates.length === 0) {
  candidates = models;
}

// Score each model
const scoredModels = candidates.map(model => {
  let score = model.performanceRating;

  // Complexity matching
  if (complexity > 8 && model.performanceRating > 9) score += 2;
  if (complexity < 4 && model.specialties.includes('cost_effective')) score += 2;

  // Token limit matching
  if (estimatedTokens > model.contextWindow) score -= 10;

  // Cost efficiency for simple tasks
  if (complexity < 5 && model.costPer1kTokens < 0.001) score += 1;

  return { model, score };
});

// Sort by score and select best
scored Models.sort((a, b) => b.score - a.score);
const selectedModel = scoredModels[0].model;

// Calculate cost estimate
const costEstimate = (estimatedTokens / 1000) * selectedModel.costPer1kTokens;

return {
  json: {
    ...$input.item.json,
    selectedModel: selectedModel.id,
    modelName: selectedModel.name,
    costEstimate,
    reasoning: `Selected ${selectedModel.name} for ${taskType} task with complexity ${complexity}/10. Cost: $${costEstimate.toFixed(4)}`
  }
};
